function dfs(u, parent) {
    const dp0 = Array(k + 1).fill(-INF), dp1 = Array(k + 1).fill(-INF), dp2 = Array(k + 1).fill(-INF);
    dp0[u][0] = dp1[u][1] = 0;
    for (const v of children[u]) {
        dfs(v, u);
        const ndp0 = Array(k + 1).fill(-INF), ndp1 = Array(k + 1).fill(-INF), ndp2 = Array(k + 1).fill(-INF);
        for (let i = 0; i <= k; i++) for (let j = 0; j + i <= k; j++) {
            ndp0[i + j] = Math.max(ndp0[i + j], dp0[u][i] + max(dp0[v][j], dp1[v][j], dp2[v][j]));
            ndp1[i + j] = Math.max(ndp1[i + j], dp1[u][i] + max(dp0[v][j], dp2[v][j]));
            ndp2[i + j] = Math.max(ndp2[i + j], dp2[u][i] + dp0[v][j]);
        }
        dp0 = ndp0; dp1 = ndp1; dp2 = ndp2;
    }
}
```

