function maxKSubarraysSum(A, k) {
  const n = A.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + A[i];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // skip i
      dp[i][t] = Math.max(dp[i][t], dp[i - 1][t]);
      if (t > 0) {
        for (let s = 1; s <= i; s++) {
          const sum = P[i] - P[s - 1];
          const prev = (s >= 2) ? dp[s - 2][t - 1] : (t - 1 === 0 ? 0 : -Infinity);
          const cand = sum + prev;
          if (cand > dp[i][t]) {
            dp[i][t] = cand;
            take[i][t] = s;
          }
        }
      }
    }
  }
  // reconstruction would trace back using 'take' from (n, bestT)
  return { maxSum: dp[n][0], blocks: [] };
}
```
